// Stack: primitives
let a = 5;          // stack: a → 5
let b = a;          // stack: b → 5 (copy)
a = 10;             // stack: a → 10 (b is still 5)

// Heap: objects
let obj1 = { x: 1 }; // heap: {x:1}, stack: obj1 → reference
let obj2 = obj1;      // stack: obj2 → same reference
obj1.x = 2;
console.log(obj2.x);  // 2 (both point to same object!)

function createObjects() {
  let obj1 = { name: "reachable" };  // reachable from this function
  let obj2 = { name: "also reachable" };
  return obj1;  // only obj1 is returned
  // obj2 is unreachable after this function returns
}

let result = createObjects();
// result → obj1 (reachable)
// obj2 is unreachable → garbage collected

// Break reference to free memory
result = null;  // now obj1 is also unreachable → collected

// Short-lived objects → young generation
function processRequests() {
  for (let i = 0; i < 1000; i++) {
    let temp = { data: i };  // created and destroyed each iteration
    // temp becomes unreachable → Scavenger collects it
  }
}

// Long-lived objects → old generation
let cache = {};
function addToCache(key, value) {
  cache[key] = value;  // lives until explicitly deleted
}
// cache grows over time → eventually Mark-Compact collects dead entries
